    <BrowserDebugHostContext.Provider value={{ host, environment }}>
      {children}
    </BrowserDebugHostContext.Provider>
  );
}

export function useBrowserDebugHost(): BrowserDebugHostContextValue {
  return useContext(BrowserDebugHostContext);
}

