      data: {
        version: BROWSER_BRIDGE_VERSION,
        type: "dam-hopper:navigation",
        nonce: "nonce",
        requestId: "request",
        url: target.url,
      },
    };

    expect(
      bridgeEventToHostEvent(
        { ...base, label: "other" },
        target,
        1,
        profileId,
        sessionId,
      ),
    ).toBeNull();
    expect(
      bridgeEventToHostEvent(
        { ...base, origin: "https://other.example" },
        target,
        1,
        profileId,
        sessionId,
      ),
    ).toBeNull();
    expect(
      bridgeEventToHostEvent(
        { ...base, data: { ...base.data, url: "" } },
