          version: 1,
          type: "dam-hopper:console",
          nonce: "nonce",
          requestId: "request",
          level: "warn",
          message: "slow",
        },
      },
      target,
      1,
      profileId,
      sessionId,
    );

    expect(selectionEvent).toMatchObject({ type: "selection", selection });
